messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Three.js Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
        #timer {
            position: absolute;
            top: 20px;
            left: 50%;
            transform: translateX(-50%);
            font-family: Arial, sans-serif;
            font-size: 24px;
            font-weight: bold;
            color: white;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.7);
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="timer">RACE LOOP</div>
    <!-- Import map to configure the module loader -->
    <script type="importmap">
        {
            "imports": {
                "three": "./three.module.js"
            }
        }
    </script>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TOTAL_RACE_DISTANCE = 1000;
        const FINISH_LINE_POS = 500;
        const TRACK_WIDTH = 40;
        const LANE_WIDTH = 15;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 50, 800);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(100, 200, 100);
        dirLight.castShadow = true;
        dirLight.shadow.camera.left = -100;
        dirLight.shadow.camera.right = 100;
        dirLight.shadow.camera.top = 100;
        dirLight.shadow.camera.bottom = -100;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(500, 2000);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x228B22 }); // Forest Green
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.5;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track
        const trackGeo = new THREE.PlaneGeometry(TRACK_WIDTH, 2000);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333 }); // Asphalt Grey
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.position.y = 0.1;
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line (Checkerboard pattern)
        const finishLineGeo = new THREE.PlaneGeometry(TRACK_WIDTH, 20);
        const finishLineMat = new THREE.MeshStandardMaterial({ 
            color: 0xFFFFFF,
            side: THREE.DoubleSide
        });
        const finishLine = new THREE.Mesh(finishLineGeo, finishLineMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.y = 0.2;
        finishLine.position.z = FINISH_LINE_POS;
        scene.add(finishLine);

        // Finish Line Stripes
        const stripeCount = 10;
        const stripeGeo = new THREE.PlaneGeometry((TRACK_WIDTH / stripeCount) - 0.5, 20);
        const stripeMat = new THREE.MeshStandardMaterial({ color: 0x000000 });

        for(let i=0; i<stripeCount; i++) {
            const stripe = new THREE.Mesh(stripeGeo, stripeMat);
            stripe.rotation.x = -Math.PI / 2;
            stripe.position.y = 0.3;
            stripe.position.z = FINISH_LINE_POS;
            stripe.position.x = -(TRACK_WIDTH/2) + (i * (TRACK_WIDTH/stripeCount));
            scene.add(stripe);
        }

        // --- Car Factory ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(4, 2, 8);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.4 });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 1.5;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(3.5, 1.5, 4);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.2 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = 3;
            cabin.position.z = -0.5;
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.8, 0.8, 1, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
            wheelGeo.rotateZ(Math.PI / 2);

            const positions = [
                { x: -2, z: 2.5 }, { x: 2, z: 2.5 },
                { x: -2, z: -2.5 }, { x: 2, z: -2.5 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.position.set(pos.x, 0.8, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            return carGroup;
        }

        // --- Instantiate Cars ---
        const carRed = createCar(0xFF0000); // Red
        carRed.position.set(-LANE_WIDTH, 0, 0);
        scene.add(carRed);

        const carBlue = createCar(0x0000FF); // Blue
        carBlue.position.set(LANE_WIDTH, 0, 0);
        scene.add(carBlue);

        // --- Animation State ---
        let time = 0;
        const clock = new THREE.Clock();

        // --- Animation Loop ---
        function animate() {
            requestAnimationFrame(animate);

            const dt = clock.getDelta();
            time += dt;

            // Calculate Race Progress
            // We use a sine wave to simulate the race:
            // t goes from 0 to 2*PI.
            // We want positions to go from 0 to TOTAL_RACE_DISTANCE.

            // Reset loop logic:
            // We will map time to a normalized progress 0 -> 1, then reset.
            const loopDuration = 15; // seconds per loop
            const cycle = (time % loopDuration) / loopDuration; // 0.0 to 1.0

            // Define speeds based on the narrative
            // Blue starts fast, slows down.
            // Red starts slow, accelerates, then finishes.

            // Mathematical easing functions to create the narrative

            // Blue: High initial velocity, then decelerates (parabolic arc)
            // 1 - cycle creates a deceleration curve.
            const blueSpeed = 1 - (cycle * 0.4); // Slows down significantly
            const blueProgress = cycle * (1 - cycle) * 4; // Simple bell curve shape for progress

            // Red: Low initial velocity, accelerates mid-race, finishes strong.
            // cycle^2 creates acceleration.
            const redSpeed = cycle * 2; 
            const redProgress = (cycle * cycle) * 1.5; // Exponential growth

            // Normalize progress to distance
            // We map 0..1 progress to 0..FINISH_LINE_POS
            // But we want to loop, so we need to ensure they cross the line.

            // Let's actually just use a custom easing function for Z position directly
            // to ensure they loop perfectly.

            // Z = -Distance. Start at 0, go to -500.
            const maxDist = FINISH_LINE_POS;

            // Blue Car Logic: Leads early, Red overtakes.
            // We want Blue at approx 60% of track at 40% time, then Red passes.

            const t = cycle;

            // Blue: Fast start, slow finish.
            // t=0 -> 0. t=1 -> 0 (loop)
            // Shape: High peak early.
            const blueZ = -Math.sin(t * Math.PI) * 300; 
            // This gives a smooth arc: 0 -> -300 -> 0. Not enough distance.

            // Let's try a custom approach for precise narrative
            // We want Red to win.

            // Reset function for loop
            // We will simply interpolate between start and finish, but speed varies.

            // Let's calculate absolute distance based on time.
            // We want the loop to take 'loopDuration' seconds.
            // We want the cars to travel 'maxDist' distance.

            // Simple Easing for narrative:
            // Blue: constant speed, but we will slow it down visually near the end?
            // No, simpler: Just calculate position based on time.

            // Let's define positions explicitly using a function of time t (0 to 1)
            // to ensure the "Overtake" happens.

            // t=0: both at 0.
            // t=0.5: Blue at 200, Red at 100.
            // t=0.8: Blue at 250, Red at 260 (Overtake).
            // t=1.0: Red at 500 (Finish), Blue at 400 (behind).
            // t=1.0+: Loop back to 0.

            // However, the requirement says "After the red car crosses the finish line the race resets".
            // So at t=1, Red is at 500. Then immediately at t=1+epsilon, both reset to 0.

            // Let's use a custom interpolation.
            const t = time / loopDuration;
            const progress = t % 1; // 0 to 1

            // Blue Car: High start, slows down, stays behind.
            // Curve: Starts steep, flattens out.
            const bluePos = Math.sin(progress * Math.PI) * 350; // Max 350 (doesn't reach finish)

            // Red Car: Starts slow, accelerates, crosses finish.
            // Curve: Starts flat, goes steep at end.
            // Using cubic power for acceleration: progress^3
            // Scale to reach 500 at progress=1.
            const redPos = Math.pow(progress, 2.5) * 500;

            // Apply Positions (Z is forward, negative is forward)
            carBlue.position.z = -bluePos;
            carRed.position.z = -redPos;

            // Camera Follow Logic
            // Camera needs to keep both cars in view.
            // Calculate midpoint between cars.
            const midX = (carBlue.position.x + carRed.position.x) / 2;
            const midZ = (carBlue.position.z + carRed.position.z) / 2;

            // Move camera towards the lead car, but keep a bit of distance
            // We want to see the finish line approaching.
            const targetZ = midZ - 40; // Camera is behind
            const targetX = midX;

            // Smooth camera movement
            camera.position.z += (targetZ - camera.position.z) * 0.1;
            camera.position.x += (targetX - camera.position.x) * 0.1;
            camera.position.y = 15; // Keep camera height constant

            camera.lookAt(midX, 0, midZ + 10);

            // Render
            renderer.render(scene, camera);
        }

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
